Both operations leave both stacks unchanged: an out-of-bounds deletion raises `ValueError` before recording anything; inserting `''` returns without recording anything. Invalid cursor moves raise `TypeError` for a non-integer or `ValueError` for an out-of-range position, with all state unchanged. Empty undo and redo return `False`.

```python
class Buffer:
    LIMIT = 4

    def __init__(self, text=''):
        if not isinstance(text, str):
            raise TypeError('text must be a string')
        self.text, self.cursor = text, len(text)
        self.undo_stack, self.redo_stack = [], []

    def _push_undo(self):
        self.undo_stack.append((self.text, self.cursor))
        if len(self.undo_stack) > self.LIMIT:
            del self.undo_stack[0]

    def move(self, position):
        if type(position) is not int:
            raise TypeError('position must be an integer')
        if not 0 <= position <= len(self.text):
            raise ValueError('cursor out of bounds')
        self.cursor = position

    def insert(self, s):
        if not isinstance(s, str):
            raise TypeError('insertion must be a string')
        if not s:
            return
        self._push_undo()
        self.redo_stack.clear()
        p = self.cursor
        self.text = self.text[:p] + s + self.text[p:]
        self.cursor = p + len(s)

    def delete(self, count):
        if type(count) is not int:
            raise TypeError('count must be an integer')
        if count < 0 or count > len(self.text) - self.cursor:
            raise ValueError('deletion out of bounds')
        if not count:
            return
        self._push_undo()
        self.redo_stack.clear()
        p = self.cursor
        self.text = self.text[:p] + self.text[p + count:]

    def undo(self):
        if not self.undo_stack:
            return False
        self.redo_stack.append((self.text, self.cursor))
        self.text, self.cursor = self.undo_stack.pop()
        return True

    def redo(self):
        if not self.redo_stack:
            return False
        self._push_undo()
        self.text, self.cursor = self.redo_stack.pop()
        return True


if __name__ == '__main__':
    b = Buffer()
    for c in 'abcde':
        b.insert(c)
    assert len(b.undo_stack) == 4
    for _ in range(4):
        assert b.undo()
    assert (b.text, b.cursor) == ('a', 1) and not b.undo()

    b = Buffer('a🙂b')
    b.move(1)
    b.delete(1)
    assert (b.text, b.cursor) == ('ab', 1)
    b.move(2)
    assert b.undo() and (b.text, b.cursor) == ('a🙂b', 1)
    assert b.redo() and (b.text, b.cursor) == ('ab', 2)
    assert b.undo()
    b.insert('X')
    assert (b.text, b.cursor) == ('aX🙂b', 2) and not b.redo()

    before = (b.text, b.cursor, b.undo_stack[:], b.redo_stack[:])
    b.insert('')
    for action in (lambda: b.delete(99), lambda: b.move(-1)):
        try:
            action()
        except ValueError:
            pass
        else:
            raise AssertionError('expected ValueError')
    assert (b.text, b.cursor, b.undo_stack, b.redo_stack) == before
```

The reducer below treats an event ID as seen on first arrival, even if that event is rejected. Only accepted events advance a booking’s version. Those choices are **underspecified**: if rejected IDs or versions should be handled differently, the policy needs clarification. An unknown cancellation remains unresolved and does not create a booking.

Events are dictionaries with `id`, `booking`, `version`, `action`, `effective`, and, for allocations, `units`. Body comparison includes every field except `id`.

```python
def reduce_ledger(events, capacity=10):
    seen = set()
    bookings = {}  # booking -> {version, body, units}
    outcomes = []

    for event in events:
        event_id = event['id']
        if event_id in seen:
            outcomes.append((event_id, 'ignored'))
            continue
        seen.add(event_id)

        booking = event['booking']
        version = event['version']
        action = event['action']
        if action not in ('allocate', 'cancel'):
            raise ValueError(f'Unknown action: {action!r}')
        if action == 'allocate':
            units = event['units']
            if type(units) is not int or units < 0:
                raise ValueError('Allocation must be a nonnegative integer')
        else:
            units = 0

        body = {k: v for k, v in event.items() if k != 'id'}
        current = bookings.get(booking)

        if current is not None and version < current['version']:
            result = 'stale'
        elif current is not None and version == current['version']:
            result = 'ignored' if body == current['body'] else 'conflict'
        elif current is None and action == 'cancel':
            result = 'unresolved'
        else:
            used = sum(item['units'] for item in bookings.values())
            old_units = current['units'] if current else 0
            if used - old_units + units > capacity:
                result = 'capacity-rejected'
            else:
                bookings[booking] = {
                    'version': version, 'body': body, 'units': units
                }
                result = 'accepted'
        outcomes.append((event_id, result))

    free = capacity - sum(item['units'] for item in bookings.values())
    return bookings, free, outcomes
```

A new ID with an identical body and equal version is classified as `ignored`; the original rules do not explicitly name that case. The function assumes comparable versions, valid required fields, and a valid nonnegative capacity. Effective dates participate in body comparison but never change arrival order.

